Chart3(fig_title="Fig.4_r.jpeg", variable='r', label="Rate of profit", min=0, max=0, sce1=1, sce2=2, sce3=3, legend_x=0.25, legend_y=0.92)
Chart3(fig_title="Fig.5_beta.jpeg", variable='beta', label="Share of green investment", min=0, max=0, sce1=1, sce2=2, sce3=3, legend_x=0.25, legend_y=0.92)
Chart3(fig_title="Fig.6_CI.jpeg", variable='CI', label=expression("CO"[2]*" intensity"), min=0, max=0, sce1=1, sce2=2, sce3=3, legend_x=0.25, legend_y=0.92)
Chart3(fig_title="Fig.7_EMIS_F.jpeg", variable='EMIS_F', label=expression("Fossil CO"[2]*" emissions (Gt)"), min=0, max=0, sce1=1, sce2=2, sce3=3, legend_x=0.25, legend_y=0.92)

